#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int isSubsequence(const char *a, const char *b) {
    int i = 0;
    int la = (int)strlen(a);
    for (int j = 0; b[j] != '\0'; j++) {
        if (i < la && a[i] == b[j]) i++;
    }
    return i == la;
}

static int cmpLenDesc(const void *x, const void *y) {
    const char *a = *(const char * const *)x;
    const char *b = *(const char * const *)y;
    int la = (int)strlen(a);
    int lb = (int)strlen(b);
    return lb - la;
}

int findLUSlength(char **strs, int strsSize) {
    char **sorted = (char **)malloc(strsSize * sizeof(char *));
    for (int i = 0; i < strsSize; i++) sorted[i] = strs[i];
    qsort(sorted, strsSize, sizeof(char *), cmpLenDesc);

    for (int i = 0; i < strsSize; i++) {
        int count = 0;
        for (int j = 0; j < strsSize; j++) {
            if (strcmp(sorted[i], strs[j]) == 0) count++;
        }
        if (count != 1) continue;

        int uncommon = 1;
        for (int j = 0; j < strsSize; j++) {
            if (strcmp(sorted[i], strs[j]) != 0 &&
                isSubsequence(sorted[i], strs[j])) {
                uncommon = 0;
                break;
            }
        }
        if (uncommon) {
            int ans = (int)strlen(sorted[i]);
            free(sorted);
            return ans;
        }
    }

    free(sorted);
    return -1;
}

