class Solution {
public:
    bool isSubsequence(const string& a, const string& b) {
        int i = 0;
        for (char ch : b) {
            if (i < (int)a.size() && a[i] == ch) i++;
        }
        return i == (int)a.size();
    }

    int findLUSlength(vector<string>& strs) {
        vector<string> sorted = strs;
        sort(sorted.begin(), sorted.end(),
             [](const string& a, const string& b) {
                 return a.size() > b.size();
             });

        for (const string& s : sorted) {
            int count = 0;
            for (const string& t : strs) {
                if (t == s) count++;
            }
            if (count != 1) continue;

            bool uncommon = true;
            for (const string& t : strs) {
                if (t != s && isSubsequence(s, t)) {
                    uncommon = false;
                    break;
                }
            }
            if (uncommon) return (int)s.size();
        }
        return -1;
    }
};

