class Solution {
    private boolean isSubsequence(String a, String b) {
        int i = 0;
        for (int j = 0; j < b.length(); j++) {
            if (i < a.length() && a.charAt(i) == b.charAt(j)) i++;
        }
        return i == a.length();
    }

    public int findLUSlength(String[] strs) {
        String[] sorted = strs.clone();
        Arrays.sort(sorted, (a, b) -> Integer.compare(b.length(), a.length()));

        for (String s : sorted) {
            int count = 0;
            for (String t : strs) {
                if (t.equals(s)) count++;
            }
            if (count != 1) continue;

            boolean uncommon = true;
            for (String t : strs) {
                if (!t.equals(s) && isSubsequence(s, t)) {
                    uncommon = false;
                    break;
                }
            }
            if (uncommon) return s.length();
        }
        return -1;
    }
}

