        def is_subsequence(a: str, b: str) -> bool:
            i = 0
            for ch in b:
                if i < len(a) and a[i] == ch:
                    i += 1
            return i == len(a)

        for s in sorted(strs, key=len, reverse=True):
            if strs.count(s) != 1:
                continue
            if all(not is_subsequence(s, t) for t in strs if t != s):
                return len(s)
        return -1

